class Solution:
    def maxProductPath(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        @lru_cache(None)
        def fn(i, j): 
            """Return maximum & minimum products ending at (i, j)."""
            if i == 0 and j == 0: return grid[0][0], grid[0][0]
            if i < 0 or j < 0: return -inf, inf
            if grid[i][j] == 0: return 0, 0
            mx1, mn1 = fn(i-1, j) # from top
            mx2, mn2 = fn(i, j-1) # from left 
            mx, mn = max(mx1, mx2)*grid[i][j], min(mn1, mn2)*grid[i][j]
            return (mx, mn) if grid[i][j] > 0 else (mn, mx)

        mx, _ = fn(m-1, n-1)
        return -1 if mx < 0 else mx % 1_000_000_007

class Solution(object):
    def bestTeamScore(self, scores, ages):
        l = len(scores)
        mapped = [[ages[i], scores[i]] for i in range(l)]
        mapped = sorted(mapped, key = lambda x : (x[0], x[1]))
        dp = [i[1] for i in mapped]

        for i in range(l):
            for j in range(0, i):
                if mapped[j][1] <= mapped[i][1]:
                    dp[i] = max(dp[i], mapped[i][1] + dp[j])
                elif mapped[i][0] == mapped[j][0]:
                    dp[i] = max(dp[i], mapped[i][1] + dp[j])

        return max(dp)

class Solution:
    def countSubstrings(self, s: str, t: str) -> int:
        res = 0
        for i in range(len(s)):
            for j in range(len(t)):
                miss, pos = 0, 0
                while i + pos < len(s) and j + pos < len(t) and miss < 2:
                    miss += s[i + pos] != t[j + pos]
                    res += miss == 1
                    pos += 1
        return res
